#include "editor/scene.hpp"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <limits>
#include <unordered_set>
namespace worldforge::editor {
namespace { bool finite(Vec3 v){return std::isfinite(v.x)&&std::isfinite(v.y)&&std::isfinite(v.z);} Vec3 add(Vec3 a,Vec3 b){return {a.x+b.x,a.y+b.y,a.z+b.z};} }
Node* Scene::find(Id id){auto i=std::find_if(nodes_.begin(),nodes_.end(),[&](const Node& n){return n.id==id;});return i==nodes_.end()?nullptr:&*i;}
const Node* Scene::find(Id id)const{auto i=std::find_if(nodes_.begin(),nodes_.end(),[&](const Node& n){return n.id==id;});return i==nodes_.end()?nullptr:&*i;}
void Scene::checkpoint(){undo_.push_back({nodes_,next_,selected_});if(undo_.size()>128)undo_.erase(undo_.begin());redo_.clear();}
bool Scene::descendant(Id child,Id ancestor)const{for(size_t i=0;i<=nodes_.size();++i){if(child==0)return false;if(child==ancestor)return true;auto* n=find(child);if(!n)return false;child=n->parent;}return true;}
Id Scene::create(std::string name,Id parent){if(name.empty()||name.size()>256||(parent&&!find(parent)))return 0;checkpoint();Id id=next_++;nodes_.push_back({id,parent,std::move(name)});return id;}
bool Scene::erase(Id id){if(!find(id))return false;checkpoint();std::unordered_set<Id> removed{id};bool change=true;while(change){change=false;for(const auto& n:nodes_)if(removed.count(n.parent)&&!removed.count(n.id)){removed.insert(n.id);change=true;}}nodes_.erase(std::remove_if(nodes_.begin(),nodes_.end(),[&](const Node& n){return removed.count(n.id)>0;}),nodes_.end());if(removed.count(selected_))selected_=0;return true;}
bool Scene::reparent(Id id,Id parent){auto* n=find(id);if(!n||(parent&&!find(parent))||id==parent||descendant(parent,id))return false;if(n->parent==parent)return true;checkpoint();find(id)->parent=parent;return true;}
bool Scene::rename(Id id,std::string name){if(!find(id)||name.empty()||name.size()>256)return false;checkpoint();find(id)->name=std::move(name);return true;}
bool Scene::setTransform(Id id,Transform t){if(!find(id)||!finite(t.position)||!finite(t.rotation)||!finite(t.scale)||t.scale.x==0||t.scale.y==0||t.scale.z==0)return false;checkpoint();find(id)->local=t;return true;}
bool Scene::translate(Id id,Vec3 delta){auto* n=find(id);if(!n||!finite(delta))return false;auto t=n->local;t.position=add(t.position,delta);return setTransform(id,t);}
bool Scene::setVisible(Id id,bool v){if(!find(id))return false;checkpoint();find(id)->visible=v;return true;}
bool Scene::setLocked(Id id,bool v){if(!find(id))return false;checkpoint();find(id)->locked=v;return true;}
bool Scene::select(Id id){if(id&&!find(id))return false;selected_=id;return true;}
std::vector<Id> Scene::children(Id id)const{std::vector<Id> out;for(const auto& n:nodes_)if(n.parent==id)out.push_back(n.id);return out;}
std::optional<Transform> Scene::worldTransform(Id id)const{auto* n=find(id);if(!n)return {};Transform t=n->local;Id p=n->parent;for(size_t i=0;p&&i<nodes_.size();++i){auto* parent=find(p);if(!parent)return {};t.position={parent->local.position.x+t.position.x*parent->local.scale.x,parent->local.position.y+t.position.y*parent->local.scale.y,parent->local.position.z+t.position.z*parent->local.scale.z};t.rotation=add(t.rotation,parent->local.rotation);t.scale={t.scale.x*parent->local.scale.x,t.scale.y*parent->local.scale.y,t.scale.z*parent->local.scale.z};p=parent->parent;}if(p)return {};return t;}
std::optional<Hit> Scene::pick(Ray ray,double radius)const{if(!finite(ray.origin)||!finite(ray.direction)||!std::isfinite(radius)||radius<=0)return {};double len=std::sqrt(ray.direction.x*ray.direction.x+ray.direction.y*ray.direction.y+ray.direction.z*ray.direction.z);if(len<1e-12)return {};ray.direction={ray.direction.x/len,ray.direction.y/len,ray.direction.z/len};std::optional<Hit> best;for(const auto& n:nodes_){if(!n.visible||n.locked)continue;bool eligible=true;for(Id p=n.parent;p;){auto* a=find(p);if(!a){eligible=false;break;}if(!a->visible||a->locked){eligible=false;break;}p=a->parent;}if(!eligible)continue;auto t=worldTransform(n.id);if(!t)continue;Vec3 d{t->position.x-ray.origin.x,t->position.y-ray.origin.y,t->position.z-ray.origin.z};double along=d.x*ray.direction.x+d.y*ray.direction.y+d.z*ray.direction.z;if(along<0)continue;double sq=d.x*d.x+d.y*d.y+d.z*d.z-along*along;if(sq<=radius*radius&&(!best||along<best->distance))best=Hit{n.id,along};}return best;}
bool Scene::save(const std::string& path)const{std::ofstream f(path,std::ios::binary);if(!f)return false;f<<"WORLDFORGE_SCENE 1\n"<<nodes_.size()<<' '<<next_<<' '<<selected_<<'\n'<<std::setprecision(17);for(const auto& n:nodes_){f<<n.id<<' '<<n.parent<<' '<<std::quoted(n.name)<<' '<<n.visible<<' '<<n.locked<<' ';const auto& t=n.local;f<<t.position.x<<' '<<t.position.y<<' '<<t.position.z<<' '<<t.rotation.x<<' '<<t.rotation.y<<' '<<t.rotation.z<<' '<<t.scale.x<<' '<<t.scale.y<<' '<<t.scale.z<<'\n';}return f.good();}
bool Scene::load(const std::string& path){std::ifstream f(path,std::ios::binary);if(!f)return false;std::string magic;int version=0;size_t count=0;Id next=0,sel=0;if(!(f>>magic>>version)||magic!="WORLDFORGE_SCENE"||version!=1||!(f>>count>>next>>sel)||count>1000000)return false;Scene tmp;tmp.next_=next;tmp.selected_=sel;std::unordered_set<Id> ids;Id maxId=0;for(size_t i=0;i<count;++i){Node n;auto& t=n.local;if(!(f>>n.id>>n.parent>>std::quoted(n.name)>>n.visible>>n.locked>>t.position.x>>t.position.y>>t.position.z>>t.rotation.x>>t.rotation.y>>t.rotation.z>>t.scale.x>>t.scale.y>>t.scale.z)||!n.id||!ids.insert(n.id).second||n.name.empty()||n.name.size()>256||!finite(t.position)||!finite(t.rotation)||!finite(t.scale)||t.scale.x==0||t.scale.y==0||t.scale.z==0)return false;maxId=std::max(maxId,n.id);tmp.nodes_.push_back(std::move(n));}if(next<=maxId||(sel&&!tmp.find(sel)))return false;for(const auto& n:tmp.nodes_)if((n.parent&&!tmp.find(n.parent))||tmp.descendant(n.parent,n.id))return false;checkpoint();nodes_=std::move(tmp.nodes_);next_=tmp.next_;selected_=tmp.selected_;return true;}
bool Scene::undo(){if(undo_.empty())return false;redo_.push_back({nodes_,next_,selected_});auto s=std::move(undo_.back());undo_.pop_back();nodes_=std::move(s.nodes);next_=s.next;selected_=s.selected;return true;}
bool Scene::redo(){if(redo_.empty())return false;undo_.push_back({nodes_,next_,selected_});auto s=std::move(redo_.back());redo_.pop_back();nodes_=std::move(s.nodes);next_=s.next;selected_=s.selected;return true;}
Camera orbit(Camera c,double yaw,double pitch,double distance){if(!std::isfinite(yaw)||!std::isfinite(pitch)||!std::isfinite(distance)||distance<=0)return c;pitch=std::clamp(pitch,-1.55,1.55);c.eye={c.target.x+distance*std::cos(pitch)*std::sin(yaw),c.target.y+distance*std::sin(pitch),c.target.z-distance*std::cos(pitch)*std::cos(yaw)};return c;}
}